description:
Use pak install packge `pak::pkg_install('genomation')` raise error.
```r
Error (Rpackge_install.R#62): callr subprocess failed: Invalid parent_resolve callback
```

and trace back showing here

```r
function(func, args = list()) {
  restart_remote_if_needed()
  load_private_packages()
  on.exit(restart_remote_if_needed(), add = TRUE)
  rs <- pkg_data$remote
  state <- rs$get_state()
  if (state %in% c("busy", "starting")) {
    pr <- pkg_data$ns$processx$poll(list(rs$get_poll_connection()), 5000)[[1]]
    state <- rs$get_state()
    if (state == "starting") {
      rs$read()
      state <- rs$get_state()
    }
  }
  if (state != "idle") stop("Subprocess is busy or cannot start")
  func2 <- func
  body(func2) <- substitute({
    withCallingHandlers(cliapp_message = function(msg) {
      withCallingHandlers(asNamespace("cliapp")$cli_server_default(msg), message = function(mmsg) {
        class(mmsg) <- c("callr_message", "message", "condition")
        signalCondition(mmsg)
        invokeRestart("muffleMessage")
      })
      invokeRestart("muffleMessage")
    }, `__body__`)
  }, list(`__body__` = body(func)))
  res <- withCallingHandlers(callr_message = function(msg) {
    message(msg)
    if (!is.null(findRestart("muffleMessage"))) {
      invokeRestart("muffleMessage")
    }
  }, rs$run_with_output(func2, args))
  if (!is.null(res$error)) stop(res$error)
  res$result
}
```

